// src/pages/lottery/LotteryView.tsx
import { useState, useEffect, useCallback } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';

import Container from '@mui/material/Container';
import Tabs from '@mui/material/Tabs';
import Tab from '@mui/material/Tab';
import Grid from '@mui/material/Grid';
import Box from '@mui/material/Box';
import Stack from '@mui/material/Stack';
import Card from '@mui/material/Card';
import CardContent from '@mui/material/CardContent';
import Divider from '@mui/material/Divider';
import Typography from '@mui/material/Typography';
import TextField from '@mui/material/TextField';
import InputAdornment from '@mui/material/InputAdornment';
import Chip from '@mui/material/Chip';
import Button from '@mui/material/Button';
import Pagination from '@mui/material/Pagination';
import Fab from '@mui/material/Fab';
import Drawer from '@mui/material/Drawer';
import IconButton from '@mui/material/IconButton';
import useMediaQuery from '@mui/material/useMediaQuery';
import { alpha, useTheme } from '@mui/material/styles';

import Iconify from 'src/components/iconify';
import { useTranslate } from 'src/locales';
import { useSettingsContext } from 'src/components/settings';
import { useSelector, useDispatch } from 'src/redux/store';
import { getWallet } from 'src/redux/slices/wallet';
import { fetchTchala, fetchTirages, fetchResultsByDate } from 'src/redux/slices/lottery';

type TabKey = 'lotos' | 'resultats' | 'regles' | 'tchala';

const todayISO = () => new Date().toISOString().slice(0, 10);
const fmtTime = (t?: string) => (t ? t.slice(0, 5) : '');

export default function LotteryView() {
  const { t } = useTranslate();
  const theme = useTheme();
  const mdUp = useMediaQuery(theme.breakpoints.up('md'));
  const settings = useSettingsContext();
  const dispatch = useDispatch();

  const { wallet } = useSelector((s) => s.wallet);
  const { tirages, tchala, tchalaPageSize, tchalaPage, isLoading, results } = useSelector(
    (s) => s.lottery
  );

  const [openCart, setOpenCart] = useState(false);

  useEffect(() => {
    dispatch(getWallet());
    dispatch(fetchTirages());
    dispatch(fetchTchala({ page: 1 }));
  }, [dispatch]);

  const location = useLocation();
  const navigate = useNavigate();
  const menuParam = (new URLSearchParams(location.search).get('menu') as TabKey) || 'lotos';

  const [currentTab, setCurrentTab] = useState<TabKey>(menuParam);
  const [q, setQ] = useState('');
  const [resultDate, setResultDate] = useState<string>(todayISO());

  useEffect(() => {
    if (menuParam !== currentTab) setCurrentTab(menuParam);
  }, [menuParam]); // eslint-disable-line

  useEffect(() => {
    const id = setTimeout(() => {
      if (currentTab === 'tchala') dispatch(fetchTchala({ page: 1, search: q }));
    }, 300);
    return () => clearTimeout(id);
  }, [q, currentTab, dispatch]);

  useEffect(() => {
    if (currentTab === 'resultats' && resultDate) {
      dispatch(fetchResultsByDate(resultDate));
    }
  }, [currentTab, resultDate, dispatch]);

  const handleChangeTab = useCallback(
    (_: React.SyntheticEvent, newValue: TabKey) => {
      setCurrentTab(newValue);
      navigate(`?menu=${newValue}`, { replace: true });
    },
    [navigate]
  );

  const tabs = [
    {
      value: 'resultats',
      label: t('loto.results') || 'Résultats',
      icon: <Iconify icon="mdi:chart-bar" width={24} />,
    },
    {
      value: 'tchala',
      label: t('loto.tchala') || 'Tchala',
      icon: <Iconify icon="mdi:book-open-variant" width={24} />,
    },
    {
      value: 'lotos',
      label: t('loto.lotos') || 'Lotos',
      icon: <Iconify icon="mdi:ticket-percent-outline" width={24} />,
    },
    {
      value: 'regles',
      label: t('loto.rules') || 'Règles',
      icon: <Iconify icon="mdi:help-circle-outline" width={24} />,
    },
  ] as const;

  const totalPages = Math.max(1, Math.ceil((tchala.count || 0) / tchalaPageSize));

  const CartContent = (
    <>
      <Box sx={{ px: 2, py: 1.25, display: 'flex', alignItems: 'center', gap: 1 }}>
        <Iconify icon="mdi:cart-outline" width={20} />
        <Typography variant="subtitle1" fontWeight={700}>
          {t('cart.title') || 'PANIER'}
        </Typography>
        <Box sx={{ flexGrow: 1 }} />
        {!mdUp && (
          <IconButton aria-label={t('common.close') || 'Fermer'} onClick={() => setOpenCart(false)}>
            <Iconify icon="mdi:close" width={20} />
          </IconButton>
        )}
      </Box>
      <Divider />
      <CardContent sx={{ bgcolor: (th) => alpha(th.palette.grey[500], 0.06) }}>
        <Stack alignItems="center" spacing={1.5} sx={{ py: 3 }}>
          <Iconify icon="mdi:clipboard-edit-outline" width={64} />
          <Typography variant="subtitle1" fontWeight={700} textAlign="center">
            {t('cart.empty_title') || 'Ton panier est vide'}
          </Typography>
          <Typography variant="body2" color="text.secondary" textAlign="center">
            {t('cart.empty_subtitle') || 'Ajoute tes paris en cliquant sur les cotes'}
          </Typography>
        </Stack>
      </CardContent>
      <Divider />
      <Stack spacing={1} sx={{ p: 2 }}>
        <Stack direction="row" justifyContent="space-between">
          <Typography variant="subtitle2">{t('cart.total') || 'Total'}</Typography>
          <Typography variant="subtitle2">0 {wallet?.currency}</Typography>
        </Stack>
        <Button variant="contained" color="success" size="large" fullWidth>
          {t('cart.checkout') || 'PLACER MON PARI'}
        </Button>
      </Stack>
    </>
  );

  return (
    <Container maxWidth={settings.themeStretch ? false : 'lg'}>
      <Tabs
        value={currentTab}
        onChange={handleChangeTab}
        sx={{ mb: { xs: 2, md: 4 } }}
        allowScrollButtonsMobile
        variant="scrollable"
      >
        {tabs.map((tab) => (
          <Tab key={tab.value} value={tab.value} label={tab.label} icon={tab.icon} />
        ))}
      </Tabs>

      {currentTab === 'lotos' && (
        <Grid container spacing={2}>
          <Grid item xs={12} md={8}>
            <Card>
              <CardContent>
                <Stack spacing={1.5}>
                  {tirages.length === 0 && !isLoading && (
                    <Typography variant="body2" color="text.secondary">
                      {t('loto.no_draws') || 'Aucun tirage disponible.'}
                    </Typography>
                  )}

                  {tirages.map((tr) => (
                    <Card
                      key={tr.id}
                      variant="outlined"
                      sx={{
                        borderRadius: 2,
                        px: 2,
                        py: 1.75,
                        bgcolor: alpha(theme.palette.grey[500], 0.06),
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'space-between',
                        flexWrap: 'wrap',
                        rowGap: 1,
                      }}
                    >
                      <Box sx={{ minWidth: 200 }}>
                        <Typography variant="subtitle1">{tr.name}</Typography>
                        <Stack
                          direction="row"
                          spacing={1}
                          sx={{ color: 'text.secondary', mt: 0.25 }}
                          alignItems="center"
                        >
                          <Iconify icon="fluent:lottery-24-regular" width={18} />
                          <Typography variant="caption">
                            {`${t('loto.open') || 'Ouverture'} ${fmtTime(tr.open_time)} • ${
                              t('loto.close') || 'Clôture'
                            } ${fmtTime(tr.end_time)}`}
                          </Typography>
                        </Stack>
                      </Box>
                      <Button variant="contained" color="success" size="medium">
                        {t('common.play') || 'Jouer'}
                      </Button>
                    </Card>
                  ))}
                </Stack>
              </CardContent>
            </Card>
          </Grid>

          {mdUp && (
            <Grid item xs={12} md={4}>
              <Card sx={{ position: 'sticky', top: 16 }}>{CartContent}</Card>
            </Grid>
          )}
        </Grid>
      )}

      {currentTab === 'resultats' && (
        <Card>
          <CardContent>
            <Stack spacing={2}>
              <Stack direction="row" alignItems="center" justifyContent="space-between">
                <Typography variant="h6">{t('results.title') || 'Résultats'}</Typography>
                <TextField
                  label={t('results.date_label') || 'Date du tirage'}
                  type="date"
                  size="small"
                  value={resultDate}
                  onChange={(e) => setResultDate(e.target.value)}
                  InputLabelProps={{ shrink: true }}
                />
              </Stack>

              {results.map((r) => (
                <Card key={r.id} variant="outlined" sx={{ borderRadius: 2 }}>
                  <Box sx={{ p: 2 }}>
                    <Typography variant="subtitle1">{r.tirage?.name}</Typography>
                    <Typography variant="caption" color="text.secondary">
                      {r.date}
                    </Typography>
                  </Box>
                  <Divider />
                  <Stack direction="row" spacing={1.25} sx={{ p: 2, flexWrap: 'wrap' }}>
                    <Chip label={r.ball_1} size="small" />
                    <Chip label={r.ball_2} size="small" />
                    <Chip label={r.ball_3} size="small" />
                  </Stack>
                </Card>
              ))}
            </Stack>
          </CardContent>
        </Card>
      )}

      {currentTab === 'regles' && (
        <Card>
          <CardContent>
            <Typography variant="h6" sx={{ mb: 1 }}>
              {t('rules.borlette.title') || 'Borlette'}
            </Typography>
            <Typography variant="subtitle1" sx={{ mb: 1 }}>
              {t('rules.borlette.general_title') || 'Règles Générales'}
            </Typography>
            <Typography variant="body2" paragraph>
              {t('rules.borlette.general_text') || ''}
            </Typography>
            <ul>
              <li>
                <Typography variant="body2">{t('rules.borlette.payouts.first') || ''}</Typography>
              </li>
              <li>
                <Typography variant="body2">{t('rules.borlette.payouts.second') || ''}</Typography>
              </li>
              <li>
                <Typography variant="body2">{t('rules.borlette.payouts.third') || ''}</Typography>
              </li>
            </ul>
            <Typography variant="body2" paragraph>
              {t('rules.results_url_label') || 'Résultats :'}{' '}
              <a
                href="https://www.lotterypost.com/results/ny"
                target="_blank"
                rel="noopener noreferrer"
              >
                lotterypost.com/results/ny
              </a>
            </Typography>

            <Divider sx={{ my: 2 }} />

            <Typography variant="h6" sx={{ mb: 1 }}>
              {t('rules.loto3.title') || 'Loto 3'}
            </Typography>
            <Typography variant="body2" paragraph>
              {t('rules.loto3.text') || ''}
            </Typography>
            <Typography variant="body2" paragraph>
              {t('rules.loto3.payout') || ''} {t('rules.results_url_label') || 'Résultats :'}{' '}
              <a
                href="https://www.lotterypost.com/results/ny"
                target="_blank"
                rel="noopener noreferrer"
              >
                lotterypost.com/results/ny
              </a>
            </Typography>

            <Divider sx={{ my: 2 }} />

            <Typography variant="h6" sx={{ mb: 1 }}>
              {t('rules.loto4.title') || 'Loto 4'}
            </Typography>
            <Typography variant="body2" paragraph>
              {t('rules.loto4.text') || ''}
            </Typography>
            <ul>
              <li>
                <Typography variant="body2">{t('rules.loto4.options.one') || ''}</Typography>
              </li>
              <li>
                <Typography variant="body2">{t('rules.loto4.options.two') || ''}</Typography>
              </li>
              <li>
                <Typography variant="body2">{t('rules.loto4.options.three') || ''}</Typography>
              </li>
            </ul>
            <Typography variant="body2" paragraph>
              {t('rules.results_url_label') || 'Résultats :'}{' '}
              <a
                href="https://www.lotterypost.com/results/ny"
                target="_blank"
                rel="noopener noreferrer"
              >
                lotterypost.com/results/ny
              </a>
            </Typography>

            <Divider sx={{ my: 2 }} />

            <Typography variant="h6" sx={{ mb: 1 }}>
              {t('rules.loto5.title') || 'Loto 5'}
            </Typography>
            <Typography variant="body2" paragraph>
              {t('rules.loto5.text') || ''}
            </Typography>
            <ul>
              <li>
                <Typography variant="body2">{t('rules.loto5.options.one') || ''}</Typography>
              </li>
              <li>
                <Typography variant="body2">{t('rules.loto5.options.two') || ''}</Typography>
              </li>
              <li>
                <Typography variant="body2">{t('rules.loto5.options.three') || ''}</Typography>
              </li>
            </ul>
            <Typography variant="body2" paragraph>
              {t('rules.results_url_label') || 'Résultats :'}{' '}
              <a
                href="https://www.lotterypost.com/results/ny"
                target="_blank"
                rel="noopener noreferrer"
              >
                lotterypost.com/results/ny
              </a>
            </Typography>

            <Divider sx={{ my: 2 }} />

            <Typography variant="h6" sx={{ mb: 1 }}>
              {t('rules.mariage.title') || 'Le Mariage'}
            </Typography>
            <Typography variant="body2" paragraph>
              {t('rules.mariage.text') || ''}
            </Typography>
            <Typography variant="body2" paragraph>
              {t('rules.mariage.payout') || ''}
            </Typography>
          </CardContent>
        </Card>
      )}

      {currentTab === 'tchala' && (
        <Card>
          <CardContent>
            <Stack spacing={2}>
              <TextField
                value={q}
                onChange={(e) => setQ(e.target.value)}
                placeholder={t('loto.search_dream') || 'Quel est votre rêve ?'}
                InputProps={{
                  startAdornment: (
                    <InputAdornment position="start">
                      <Iconify icon="mdi:magnify" width={20} />
                    </InputAdornment>
                  ),
                }}
              />
              <Card variant="outlined" sx={{ borderRadius: 2 }}>
                <Box
                  sx={{
                    px: 2,
                    py: 1.25,
                    bgcolor: 'primary.dark',
                    color: 'primary.contrastText',
                    borderTopLeftRadius: 8,
                    borderTopRightRadius: 8,
                  }}
                >
                  <Stack direction="row" justifyContent="space-between">
                    <Typography fontWeight={700}>{t('loto.search_dream') || 'Rêve'}</Typography>
                    <Typography fontWeight={700}>{t('loto.tchala') || 'Numéro'} </Typography>
                  </Stack>
                </Box>
                <Stack sx={{ maxHeight: 520, overflow: 'auto', p: 1 }}>
                  {tchala.results.map((row) => (
                    <Stack
                      key={row.id}
                      direction="row"
                      alignItems="center"
                      justifyContent="space-between"
                      sx={{
                        px: 1.25,
                        py: 1,
                        borderBottom: (th) => `1px solid ${alpha(th.palette.grey[500], 0.16)}`,
                      }}
                    >
                      <Typography>{row.label}</Typography>
                      <Stack direction="row" spacing={1} flexWrap="wrap">
                        {row.numbers.map((n: string, i: number) => (
                          <Chip key={i} label={n} size="small" />
                        ))}
                      </Stack>
                    </Stack>
                  ))}
                </Stack>
              </Card>

              <Stack direction="row" justifyContent="center">
                <Pagination
                  page={tchalaPage}
                  count={totalPages}
                  onChange={(_, p) => dispatch(fetchTchala({ page: p, search: q }))}
                  color="primary"
                  size="small"
                />
              </Stack>
            </Stack>
          </CardContent>
        </Card>
      )}

      {!mdUp && currentTab === 'lotos' && (
        <>
          {!openCart && (
            <Fab
              aria-label={t('cart.title') || 'PANIER'}
              color="success"
              onClick={() => setOpenCart(true)}
              sx={{ position: 'fixed', right: 16, bottom: 100, zIndex: 1400 }}
            >
              <Iconify icon="mdi:cart-outline" width={22} />
            </Fab>
          )}

          <Drawer
            anchor="right"
            open={openCart}
            onClose={() => setOpenCart(false)}
            PaperProps={{ sx: { width: '100%', maxWidth: 360 } }}
          >
            <Card
              elevation={0}
              sx={{ borderRadius: 0, height: '100%', display: 'flex', flexDirection: 'column' }}
            >
              {CartContent}
            </Card>
          </Drawer>
        </>
      )}
    </Container>
  );
}
